sensitive_village_schema	sensitive_villages	环境敏感目标（居民点）	敏感目标与空间实体	Object	\N	t	评价范围内的村庄、居民区，需重点关注其与矿区的位置关系及搬迁情况。	[]	[{"key": "name", "name_cn": "村庄名称", "value_type": "String", "unit": null, "required": true, "description": "", "extraction_hint": "识别以'村'、'庄'、'社区'结尾的实体"}, {"key": "population", "name_cn": "人口规模", "value_type": "String", "unit": "人/户", "required": false, "description": "", "extraction_hint": "提取格式如'120户、450人'，优先保留结构化数据"}, {"key": "spatial_position", "name_cn": "位置关系", "value_type": "Enum", "unit": null, "required": true, "description": "", "extraction_hint": "关键词：'位于井田内'、'受采动影响'、'错动线范围内'", "enum_options": ["井田内", "错动线内", "井田外", "边界毗邻"]}, {"key": "distance_desc", "name_cn": "方位距离", "value_type": "String", "unit": null, "required": false, "description": "", "extraction_hint": "例如：工业广场东南侧500m处"}, {"key": "relocation_status", "name_cn": "搬迁状态", "value_type": "Enum", "unit": null, "required": false, "description": "", "extraction_hint": "根据'拟实施搬迁'、'不涉及搬迁'判断", "enum_options": ["拟搬迁", "不搬迁/留守", "已搬迁"]}]	[{"rule_id": "rule_0235e8f4", "rule_name": "SPATIAL_CONFLICT", "condition": {"source": "spatial_position", "target": "project_basic_info"}, "actions": [{"type": "create_edge", "relation": "SPATIAL_CONFLICT", "target": "project_basic_info"}], "description": "IF spatial_position IN ['错动线内', '井田内'] AND relocation_status != '已搬迁' THEN CreateEdge(Project, Village, 'Risk: 压煤/沉陷影响')"}]	{"legacy_category": "社会环境敏感区", "extraction_prompt": "在'环境现状调查'或'保护目标'章节查找所有村庄列表。对于每个村庄，提取其名称、人口、与井田边界的位置关系及方位距离。"}	2026-04-30 06:38:06.039943	2026-04-30 06:38:06.039955	coal
